package ports

import (
	"context"

	"github.com/kape-io/kape/operator/infra/api/v1alpha1"
)

// DaemonTokenStore owns the controller→daemon bearer token (ADR-0083 D5).
//
// The token is generated by the operator, not declared by the user: it is
// plumbing between two objects the operator already owns, so a CR field would
// only invite the value into git and into CR status. Ensure returns the name of
// the Secret holding it; the controller Deployment receives it through a
// SecretKeyRef and injects it into each sandbox it creates.
//
// Ensure must be idempotent: an existing token is reused, never regenerated —
// rotating it would 401 every sandbox already running.
type DaemonTokenStore interface {
	Ensure(ctx context.Context, server *v1alpha1.KapeAgentServer) (secretName string, err error)
}
